{"file_path":"src/parser.js","content":"/**
 * Parser for the limiter file format
 */

const VALID_NAME_CHARS = /^[A-Za-z0-9_.\/:~-]+$/;
const DIGIT_PATTERN = /^\d+$/;

export class Parser {
  constructor() {
    this.policies = new Map();
    this.routes = [];
    this.events = [];
    this.seenFirstEvent = false;
  }

  parse(input) {
    const lines = input.split('\n');
    // Drop empty tail from trailing newline
    if (lines.length > 0 && lines[lines.length - 1] === '') {
      lines.pop();
    }

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const trimmed = line.trim();

      // Ignore empty lines and comments
      if (trimmed === '' || trimmed.startsWith('#')) {
        continue;
      }

      // Split on runs of whitespace
      const tokens = trimmed.split(/\s+/);
      const directive = tokens[0];

      try {
        if (directive === 'bucket') {
          this.parseBucket(tokens, i + 1);
        } else if (directive === 'window') {
          this.parseWindow(tokens, i + 1);
        } else if (directive === 'route') {
          this.parseRoute(tokens, i + 1);
        } else if (directive === 'event') {
          this.parseEvent(tokens, i + 1);
        } else {
          throw new ParseError(i + 1, `unknown directive ${directive}`);
        }
      } catch (error) {
        if (error instanceof ParseError) {
          throw error;
        }
        throw new ParseError(i + 1, error.message);
      }
    }

    return {
      policies: this.policies,
      routes: this.routes,
      events: this.events
    };
  }

  parseBucket(tokens, lineNum) {
    if (this.seenFirstEvent) {
      throw new ParseError(lineNum, 'declarations must come before the first event');
    }

    if (tokens.length !== 5) {
      throw new ParseError(lineNum, 'expected bucket <name> <capacity> <refill> <per>');
    }

    const [, name, capacityStr, refillStr, perStr] = tokens;

    if (!this.isValidName(name)) {
      throw new ParseError(lineNum, `invalid policy name ${name}`);
    }

    if (this.policies.has(name)) {
      throw new ParseError(lineNum, `policy ${name} is declared twice`);
    }

    const capacity = this.parseInteger(capacityStr, lineNum, 'capacity', 1);
    const refill = this.parseInteger(refillStr, lineNum, 'refill', 0);
    const per = this.parseInteger(perStr, lineNum, 'per', 1);

    this.policies.set(name, {
      type: 'bucket',
      name,
      capacity,
      refill,
      per
    });
  }

  parseWindow(tokens, lineNum) {
    if (this.seenFirstEvent) {
      throw new ParseError(lineNum, 'declarations must come before the first event');
    }

    if (tokens.length !== 4) {
      throw new ParseError(lineNum, 'expected window <name> <limit> <span>');
    }

    const [, name, limitStr, spanStr] = tokens;

    if (!this.isValidName(name)) {
      throw new ParseError(lineNum, `invalid policy name ${name}`);
    }

    if (this.policies.has(name)) {
      throw new ParseError(lineNum, `policy ${name} is declared twice`);
    }

    const limit = this.parseInteger(limitStr, lineNum, 'limit', 0);
    const span = this.parseInteger(spanStr, lineNum, 'span', 1);

    this.policies.set(name, {
      type: 'window',
      name,
      limit,
      span
    });
  }

  parseRoute(tokens, lineNum) {
    if (this.seenFirstEvent) {
      throw new ParseError(lineNum, 'declarations must come before the first event');
    }

    if (tokens.length < 3) {
      throw new ParseError(lineNum, 'expected route <prefix> <policy>...');
    }

    const [, prefix, ...policyNames] = tokens;

    if (!this.isValidName(prefix)) {
      throw new ParseError(lineNum, `invalid route prefix ${prefix}`);
    }

    // Check for duplicate prefix
    for (const route of this.routes) {
      if (route.prefix === prefix) {
        throw new ParseError(lineNum, `prefix ${prefix} is routed twice`);
      }
    }

    // Check that all policies exist
    for (const policyName of policyNames) {
      if (!this.policies.has(policyName)) {
        throw new ParseError(lineNum, `unknown policy ${policyName}`);
      }
    }

    this.routes.push({
      prefix,
      policies: policyNames
    });
  }

  parseEvent(tokens, lineNum) {
    this.seenFirstEvent = true;

    if (tokens.length !== 3) {
      throw new ParseError(lineNum, 'expected event <tick> <key>');
    }

    const [, tickStr, key] = tokens;

    if (!this.isValidName(key)) {
      throw new ParseError(lineNum, `invalid key ${key}`);
    }

    const tick = this.parseInteger(tickStr, lineNum, 'tick', 0);

    // Check that ticks don't go backwards
    if (this.events.length > 0) {
      const lastTick = this.events[this.events.length - 1].tick;
      if (tick < lastTick) {
        throw new ParseError(lineNum, `tick ${tick} is before tick ${lastTick}`);
      }
    }

    this.events.push({ tick, key });
  }

  isValidName(name) {
    return name.length > 0 && VALID_NAME_CHARS.test(name);
  }

  parseInteger(str, lineNum, fieldName, minimum) {
    if (!DIGIT_PATTERN.test(str)) {
      throw new ParseError(lineNum, `${fieldName} must be an integer of at least ${minimum}`);
    }

    // Check for leading zeros
    if (str.length > 1 && str[0] === '0') {
      throw new ParseError(lineNum, `${fieldName} must be an integer of at least ${minimum}`);
    }

    const value = parseInt(str, 10);

    if (value < minimum) {
      throw new ParseError(lineNum, `${fieldName} must be an integer of at least ${minimum}`);
    }

    return value;
  }
}

class ParseError extends Error {
  constructor(lineNum, reason) {
    super(`error: line ${lineNum}: ${reason}\n`);
    this.lineNum = lineNum;
    this.reason = reason;
  }
}
"}

