          for (const policyName of policyNames) {
            const state = keyState.get(policyName);
            const policyDef = this.policiesDefinition.get(policyName);
            this.recordEvent(policyDef, state, tick);
          }
        }

        this.results.push({
          tick,
          key,
          allowed,
          deniedBy: firstDenialPolicy
        });
      }
    }

    return this.results;
  }

