/**
 * Parser for the limiter file format.
 */

const TOKEN_RE = /^[A-Za-z0-9_.\/:-]+$/
const COUNT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function fail(line, reason) {
  throw new ParseError(line, reason)
}

function isToken(word) {
  return TOKEN_RE.test(word)
}

function count(word, line, field, least) {
  if (!COUNT_RE.test(word)) fail(line, `${field} must be an integer of at least ${least}`)
  const value = BigInt(word)
  if (value < BigInt(least)) fail(line, `${field} must be an integer of at least ${least}`)
  return value
}

/**
 * Parses the whole limiter file, returning its declarations and its log.
 */
export function parse(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const events = []
  let seenEvent = false
  let lastTick = null
  let lastTickText = null

  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'bucket') {
      if (words.length !== 5) fail(n, 'expected bucket <name> <capacity> <refill> <per>')
      const name = words[1]
      if (!isToken(name)) fail(n, `invalid policy name ${name}`)
      if (policies.has(name)) fail(n, `policy ${name} is declared twice`)
      if (seenEvent) fail(n, 'declarations must come before the first event')
      const capacity = count(words[2], n, 'capacity', 1)
      const refill = count(words[3], n, 'refill', 0)
      const per = count(words[4], n, 'per', 1)
      policies.set(name, { kind: 'bucket', name, capacity, refill, per })
    } else if (directive === 'window') {
      if (words.length !== 4) fail(n, 'expected window <name> <limit> <span>')
      const name = words[1]
      if (!isToken(name)) fail(n, `invalid policy name ${name}`)
      if (policies.has(name)) fail(n, `policy ${name} is declared twice`)
      if (seenEvent) fail(n, 'declarations must come before the first event')
      const limit = count(words[2], n, 'limit', 0)
      const span = count(words[3], n, 'span', 1)
      policies.set(name, { kind: 'window', name, limit, span })
    } else if (directive === 'route') {
      if (words.length < 3) fail(n, 'expected route <prefix> <policy>...')
      const prefix = words[1]
      if (!isToken(prefix)) fail(n, `invalid route prefix ${prefix}`)
      if (routes.some((route) => route.prefix === prefix)) {
        fail(n, `prefix ${prefix} is routed twice`)
      }
      for (let k = 2; k < words.length; k++) {
        if (!policies.has(words[k])) fail(n, `unknown policy ${words[k]}`)
      }
      if (seenEvent) fail(n, 'declarations must come before the first event')
      routes.push({ prefix, policies: words.slice(2) })
    } else if (directive === 'event') {
      if (words.length !== 3) fail(n, 'expected event <tick> <key>')
      const key = words[2]
      if (!isToken(key)) fail(n, `invalid key ${key}`)
      const tick = count(words[1], n, 'tick', 0)
      if (lastTick !== null && tick < lastTick) {
        fail(n, `tick ${words[1]} is before tick ${lastTickText}`)
      }
      lastTick = tick
      lastTickText = words[1]
      seenEvent = true
      events.push({ tick, tickText: words[1], key })
    } else {
      fail(n, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}

