/**
 * Simulator for processing events through token buckets and sliding windows
 */

export class Simulator {
  constructor(policies, routes) {
    this.policiesDefinition = policies;
    this.routes = routes;
    this.keyStates = new Map(); // key -> Map<policyName -> state>
    this.results = [];
  }

  simulate(events) {
    for (const event of events) {
      const { tick, key } = event;

      // Find the longest matching route
      const route = this.findLongestRoute(key);

      if (!route) {
        // No route matches, always allow
        this.results.push({ tick, key, allowed: true });
      } else {
        // Process through the route's policies
        const policyNames = route.policies;

        // Initialize state for this key if needed
        if (!this.keyStates.has(key)) {
          this.keyStates.set(key, new Map());
        }
        const keyState = this.keyStates.get(key);

        // Advance all policies to this tick and check if allowed
        let allowed = true;
        let firstDenialPolicy = null;

        // First pass: check if all policies allow it (and advance them)
        for (const policyName of policyNames) {
          if (!keyState.has(policyName)) {
            // Create initial state for this policy
            keyState.set(policyName, this.createPolicyState(policyName));
          }

          const state = keyState.get(policyName);
          const policyDef = this.policiesDefinition.get(policyName);

          // Advance the policy to the current tick
          this.advancePolicy(policyDef, state, tick);

          // Ask if the request is allowed
          if (!this.isAllowed(policyDef, state)) {
            allowed = false;
            if (!firstDenialPolicy) {
              firstDenialPolicy = policyName;
            }
          }
        }

        // Second pass: if allowed, record in all policies
        if (allowed) {
          for (const policyName of policyNames) {
            const state = keyState.get(policyName);
            const policyDef = this.policiesDefinition.get(policyName);
            this.recordEvent(policyDef, state, tick);
          }
        }

        this.results.push({
          tick,
          key,
          allowed,
          deniedBy: firstDenialPolicy
        });
      }
    }

    return this.results;
  }

  findLongestRoute(key) {
    let bestRoute = null;
    let bestLength = -1;

    for (const route of this.routes) {
      if (key.startsWith(route.prefix) && route.prefix.length > bestLength) {
        bestRoute = route;
        bestLength = route.prefix.length;
      }
    }

    return bestRoute;
  }

  createPolicyState(policyName) {
    const policyDef = this.policiesDefinition.get(policyName);

    if (policyDef.type === 'bucket') {
      return {
        type: 'bucket',
        tokens: policyDef.capacity,
        lastTick: null
      };
    } else if (policyDef.type === 'window') {
      return {
        type: 'window',
        ticks: [],
        lastTick: null
      };
    }

    throw new Error(`Unknown policy type: ${policyDef.type}`);
  }

  advancePolicy(policyDef, state, currentTick) {
    if (policyDef.type === 'bucket') {
      this.advanceBucket(policyDef, state, currentTick);
    } else if (policyDef.type === 'window') {
      this.advanceWindow(policyDef, state, currentTick);
    }
  }

  advanceBucket(policyDef, state, currentTick) {
    if (state.lastTick === null) {
      // First time this key reaches this policy, state is already initialized with capacity
      state.lastTick = currentTick;
    } else {
      const ticksPassed = currentTick - state.lastTick;
      const refillAmount = (policyDef.refill * ticksPassed) / policyDef.per;
      state.tokens = Math.min(state.tokens + refillAmount, policyDef.capacity);
      state.lastTick = currentTick;
    }
  }

  advanceWindow(policyDef, state, currentTick) {
    // Forget ticks outside the window (before currentTick - span)
    const cutoff = currentTick - policyDef.span;
    state.ticks = state.ticks.filter(tick => tick > cutoff);
    state.lastTick = currentTick;
  }

  isAllowed(policyDef, state) {
    if (policyDef.type === 'bucket') {
      return state.tokens >= 1;
    } else if (policyDef.type === 'window') {
      return state.ticks.length < policyDef.limit;
    }
    return true;
  }

  recordEvent(policyDef, state, tick) {
    if (policyDef.type === 'bucket') {
      state.tokens -= 1;
    } else if (policyDef.type === 'window') {
      state.ticks.push(tick);
    }
  }
}

