/**
 * Replays the event log through the declared policies.
 *
 * A bucket's tokens are kept as an exact rational: `units` counts token
 * fractions of size 1/per, so refills of a partial period never round away.
 */

function makeState(policy, tick) {
  if (policy.kind === 'bucket') {
    return { units: policy.capacity * policy.per, tick }
  }
  return { ticks: [], head: 0, tick }
}

function advance(policy, state, tick) {
  if (policy.kind === 'bucket') {
    const elapsed = tick - state.tick
    if (elapsed > 0n) {
      const ceiling = policy.capacity * policy.per
      state.units += policy.refill * elapsed
      if (state.units > ceiling) state.units = ceiling
    }
    state.tick = tick
    return
  }
  const cutoff = tick - policy.span
  while (state.head < state.ticks.length && state.ticks[state.head] <= cutoff) {
    state.head++
  }
  if (state.head > 0) {
    state.ticks = state.ticks.slice(state.head)
    state.head = 0
  }
  state.tick = tick
}

function allows(policy, state) {
  if (policy.kind === 'bucket') return state.units >= policy.per
  return BigInt(state.ticks.length - state.head) < policy.limit
}

function record(policy, state, tick) {
  if (policy.kind === 'bucket') {
    state.units -= policy.per
    return
  }
  state.ticks.push(tick)
}

function longestRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === null || route.prefix.length > best.prefix.length) best = route
    }
  }
  return best
}

export function simulate({ policies, routes, events }) {
  const states = new Map() // policy name -> Map<key, state>
  for (const name of policies.keys()) states.set(name, new Map())

  const verdicts = []
  for (const event of events) {
    const route = longestRoute(routes, event.key)
    if (route === null) {
      verdicts.push({ tick: event.tickText, key: event.key, allowed: true })
      continue
    }

    const active = []
    for (const name of route.policies) {
      const policy = policies.get(name)
      const byKey = states.get(name)
      let state = byKey.get(event.key)
      if (state === undefined) {
        state = makeState(policy, event.tick)
        byKey.set(event.key, state)
      }
      advance(policy, state, event.tick)
      active.push({ policy, state })
    }

    let denier = null
    for (const { policy, state } of active) {
      if (!allows(policy, state)) {
        denier = policy.name
        break
      }
    }

    if (denier === null) {
      for (const { policy, state } of active) record(policy, state, event.tick)
      verdicts.push({ tick: event.tickText, key: event.key, allowed: true })
    } else {
      verdicts.push({ tick: event.tickText, key: event.key, allowed: false, denier })
    }
  }
  return verdicts
}

