/**
 * Formatter for output
 */

export function formatReplay(results) {
  let output = '';
  for (const result of results) {
    if (result.allowed) {
      output += `${result.tick} ${result.key} allow\n`;
    } else {
      output += `${result.tick} ${result.key} deny ${result.deniedBy}\n`;
    }
  }
  return output;
}

export function formatSummary(results) {
  const keyCounts = new Map(); // key -> { allowed, denied }
  let totalAllowed = 0;
  let totalDenied = 0;

  for (const result of results) {
    if (!keyCounts.has(result.key)) {
      keyCounts.set(result.key, { allowed: 0, denied: 0 });
    }

    const counts = keyCounts.get(result.key);
    if (result.allowed) {
      counts.allowed++;
      totalAllowed++;
    } else {
      counts.denied++;
      totalDenied++;
    }
  }

  let output = '';

  // Sort keys in ascending order
  const sortedKeys = Array.from(keyCounts.keys()).sort();

  for (const key of sortedKeys) {
    const counts = keyCounts.get(key);
    output += `${key} allowed=${counts.allowed} denied=${counts.denied}\n`;
  }

  output += `total allowed=${totalAllowed} denied=${totalDenied}\n`;

  return output;
}

