/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync, writeSync } from 'node:fs'
import { parse, ParseError } from './parser.js'
import { simulate } from './simulator.js'
import { formatReplay, formatSummary } from './formatter.js'

function write(fd, text) {
  if (text === '') return
  const buffer = Buffer.from(text, 'utf8')
  let written = 0
  while (written < buffer.length) {
    try {
      written += writeSync(fd, buffer, written, buffer.length - written)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EPIPE') return
      throw error
    }
  }
}

function die(message) {
  write(2, `error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

const args = process.argv.slice(2)
const mode = args[0]
if (args.length !== 1 || (mode !== 'replay' && mode !== 'summary')) {
  die('usage: cli.js replay|summary')
}

let output
try {
  const verdicts = simulate(parse(readStdin()))
  output = mode === 'replay' ? formatReplay(verdicts) : formatSummary(verdicts)
} catch (error) {
  if (error instanceof ParseError) die(error.message)
  throw error
}

write(1, output)
process.exit(0)
"}

