import { readSync } from 'fs';
import { Parser } from './parser.js';
import { Simulator } from './simulator.js';
import { formatReplay, formatSummary } from './formatter.js';

const mode = process.argv[2];

if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n');
  process.exit(2);
}

// Read all input from stdin
let input = '';
let chunk;
const buffer = Buffer.alloc(4096);

try {
  while ((chunk = readSync(0, buffer, 0, 4096)) > 0) {
    input += buffer.toString('utf8', 0, chunk);
  }
} catch (e) {
  // End of input
}

const parser = new Parser();

try {
  const { policies, routes, events } = parser.parse(input);
  const simulator = new Simulator(policies, routes);
  const results = simulator.simulate(events);

  if (mode === 'replay') {
    process.stdout.write(formatReplay(results));
  } else {
    process.stdout.write(formatSummary(results));
  }
  process.exit(0);
} catch (error) {
  process.stderr.write(error.message);
  process.exit(2);
}

